class TenantRouter {
  constructor(wsManager) { this.ws = wsManager; this.current = null; this.handlers = new Map(); }
  switchTenant(tenantId) {
    if (this.current === tenantId) return;
    // cleanup old
    if (this.current != null) this.ws.unsubscribe(this.current);
    // hydrate new
    this.current = tenantId;
    this.ws.subscribe(tenantId, (ev) => this._handleEvent(ev));
  }
  _handleEvent(ev) { /* render diff via virtualization */ }
}
